    const skip = await p.$('.sr-intro-skip'); if (skip) { await skip.click().catch(()=>{}); await new Promise(r => setTimeout(r, 800)); }
    for (let i = 0; i < 6; i++) {
      await p.evaluate(i => document.querySelector('[data-story="' + i + '"]').click(), i);
      await new Promise(r => setTimeout(r, 900));
      const sw = await p.evaluate(() => document.documentElement.scrollWidth);
      await p.screenshot({ path: out + '/story-' + w + '-' + i + '.png', fullPage: true });
      console.log(w, i, 'scrollWidth', sw);
    }
    console.log('errors', JSON.stringify(errs));
    await p.close();
  }
  await b.close();
})();
